query:
mutation hardwareUpdateSettings ( $accountId:ID! $hardwareShippingSettingsUpdateSettingsInput:HardwareShippingSettingsUpdateSettingsInput!) {
	hardware ( accountId:$accountId ) {
		updateSettings ( input:$hardwareShippingSettingsUpdateSettingsInput  )  {
			settings {
				parentRestrictedIncoterm
				restrictedIncoterm
				incotermRestrictionIncludeSelf
				shippingCostVisibility
				allowEditing
			}
		}
	}	
}
